select json_build_object('spots_total',(select count(*) from public.spots),'spots_by_status',(select json_object_agg(status,c) from (select status,count(*) c from public.spots group by 1) s),'spots_community_true',(select count(*) from public.spots where community),'spots_edited_true',(select count(*) from public.spots where edited),'spots_submitted_by_not_null',(select count(*) from public.spots where submitted_by is not null),'spots_id_prefixes',(select json_object_agg(p,c) from (select regexp_replace(id,'[0-9a-f-]+$','') p,count(*) c from public.spots group by 1) s),'pending_edits',(select count(*) from public.pending_edits),'reports',(select count(*) from public.reports),'moderators',(select count(*) from public.moderators),'marks',(select count(*) from public.marks),'marks_by_type',(select coalesce(json_object_agg(mark_type,c),'{}'::json) from (select mark_type,count(*) c from public.marks group by 1) s),'routes',(select count(*) from public.routes),'sessions',(select count(*) from public.sessions),'session_climbs',(select count(*) from public.session_climbs),'auth_users',(select count(*) from auth.users),'spots_updated_at_min',(select min(updated_at) from public.spots),'spots_updated_at_max',(select max(updated_at) from public.spots)) as data;
